import random
import numpy as np

def is_covered_by_n_lines(points, n):
    if not points: return True
    if n == 0: return not points
    pts = list(points)
    lines = []
    for i in range(len(pts)):
        for j in range(i + 1, len(pts)):
            p1, p2 = pts[i], pts[j]
            a = p2[1] - p1[1]
            b = p1[0] - p2[0]
            c = p2[0]*p1[1] - p2[1]*p1[0]
            lines.append((a, b, c))
    for p in pts:
        lines.append((1, 0, -p[0]))
        lines.append((0, 1, -p[1]))

    def can_cover(remaining_pts, lines_left):
        if not remaining_pts: return True
        if lines_left == 0: return False
        p = remaining_pts[0]
        for line in lines:
            a, b, c = line
            if a*p[0] + b*p[1] + c == 0:
                new_remaining = [pt for pt in remaining_pts if not (a*pt[0] + b*pt[1] + c == 0)]
                if can_cover(new_remaining, lines_left - 1): return True
        return False
    return can_cover(pts, n)

def is_covered_by_circle(points):
    if len(points) <= 2: return True
    if len(points) == 3:
        p1, p2, p3 = list(points)
        return (p2[1]-p1[1])*(p3[0]-p2[0]) != (p3[1]-p2[1])*(p2[0]-p1[0])
    p1, p2, p3 = list(points)[:3]
    if (p2[1]-p1[1])*(p3[0]-p2[0]) == (p3[1]-p2[1])*(p2[0]-p1[0]):
        return False
    mat = np.array([[p1[0], p1[1], 1], [p2[0], p2[1], 1], [p3[0], p3[1], 1]])
    rhs = np.array([p1[0]**2 + p1[1]**2, p2[0]**2 + p2[1]**2, p3[0]**2 + p3[1]**2])
    try:
        sol = np.linalg.solve(mat, rhs)
        A, B, C = sol
        for p in points[3:]:
            if abs(A*p[0] + B*p[1] + C - (p[0]**2 + p[1]**2)) > 1e-7: return False
        return True
    except np.linalg.LinAlgError: return False

def check_S(S, n):
    if is_covered_by_n_lines(S, n): return False
    if is_covered_by_circle(S): return False
    for X in S:
        S_minus_X = [p for p in S if p != X]
        if not is_covered_by_n_lines(S_minus_X, n): return False
    return True

def search_S(n, s_size, iterations=2000):
    for _ in range(iterations):
        S = []
        while len(S) < s_size:
            p = (random.randint(0, 10), random.randint(0, 10))
            if p not in S: S.append(p)
        if check_S(S, n): return S
    return None

